		add(trie, "C", true);
		add(trie, "cAa", true);

		List<SearchResult<Integer, string>> result =
			trie.search("abccab".getBytes(), TaskMonitor.DUMMY);

		assertEquals("wrong size result list", 7, result.size());
		expect(result, 0, "a");
		expect(result, 0, "Ab");
		expect(result, 1, "bc");
		expect(result, 2, "C");
		expect(result, 3, "C");
		expect(result, 4, "a");
		expect(result, 4, "Ab");
	}

